begin;
create or replace function public.save_curriculum_draft(expected_revision integer, next_title text, next_content jsonb) returns public.curriculum_draft language plpgsql security definer set search_path='' as $$
declare d public.curriculum_draft;
begin
 if not public.is_curriculum_editor() then raise exception 'Brak uprawnień do edycji programu.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(20261021,1);
 if not extensions.jsonb_matches_schema('{"type":"object","properties":{"schemaVersion":{"const":1},"chapters":{"type":"array","items":{"type":"object","properties":{"id":{"type":"integer","minimum":1,"maximum":30},"title":{"type":"string","minLength":0,"maxLength":20000},"subtitle":{"type":"string","minLength":0,"maxLength":20000},"region":{"type":"string","minLength":0,"maxLength":20000}},"required":["id","title","subtitle","region"],"additionalProperties":false},"minItems":1,"maxItems":30},"lessons":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"chapter":{"type":"integer","minimum":1,"maximum":1000000},"order":{"type":"integer","minimum":1,"maximum":1000000},"title":{"type":"string","minLength":0,"maxLength":20000},"category":{"enum":["Technika","Rytm","Teoria","Słuch","Repertuar","Improwizacja"]},"theory":{"type":"string","minLength":0,"maxLength":20000},"steps":{"type":"array","items":{"type":"string","minLength":0,"maxLength":20000},"minItems":1,"maxItems":5000},"example":{"type":"string","minLength":0,"maxLength":20000},"criteria":{"type":"array","items":{"type":"string","minLength":0,"maxLength":20000},"minItems":1,"maxItems":5000},"mistake":{"type":"string","minLength":0,"maxLength":20000},"source":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"prerequisites":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":0,"maxItems":5000,"uniqueItems":true},"optional":{"type":"boolean"},"challenge":{"type":"boolean"},"minutes":{"type":"integer","minimum":1,"maximum":180},"sessions":{"type":"array","items":{"type":"integer","minimum":1,"maximum":1000000},"minItems":2,"maxItems":2},"branch":{"type":"string","minLength":0,"maxLength":20000},"songChoices":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":1,"maxItems":10,"uniqueItems":true}},"required":["id","chapter","order","title","category","theory","steps","example","criteria","mistake","source","prerequisites","optional","challenge","minutes"],"additionalProperties":false},"minItems":1,"maxItems":5000},"songs":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"title":{"type":"string","minLength":0,"maxLength":20000},"artist":{"type":"string","minLength":0,"maxLength":20000},"kind":{"enum":["Piosenka","Riff","Aranżacja"]},"chapter":{"type":"integer","minimum":1,"maximum":1000000},"version":{"type":"string","minLength":0,"maxLength":20000},"requirements":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":0,"maxItems":5000,"uniqueItems":true},"example":{"type":"string","maxLength":20000},"url":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000},"lesson":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"teacher":{"type":"string","minLength":0,"maxLength":20000},"language":{"type":"string","minLength":0,"maxLength":20000},"practice":{"type":"array","items":{"type":"string","minLength":0,"maxLength":20000},"minItems":1,"maxItems":5000},"criteria":{"type":"array","items":{"type":"string","minLength":0,"maxLength":20000},"minItems":1,"maxItems":5000},"nylon":{"type":"string","minLength":0,"maxLength":20000},"sessions":{"type":"array","items":{"type":"integer","minimum":1,"maximum":1000000},"minItems":2,"maxItems":2},"checkpoint":{"type":"integer","minimum":1,"maximum":1000000},"extraUrl":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000}},"required":["id","title","artist","kind","chapter","version","requirements","example"],"additionalProperties":false},"minItems":0,"maxItems":5000},"sources":{"type":"object","minProperties":1,"maxProperties":5000,"propertyNames":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"additionalProperties":{"type":"object","properties":{"title":{"type":"string","minLength":0,"maxLength":20000},"url":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000},"language":{"type":"string","minLength":0,"maxLength":20000},"access":{"type":"string","minLength":0,"maxLength":20000}},"required":["title","url","language","access"],"additionalProperties":false}}},"required":["schemaVersion","chapters","lessons","songs","sources"],"additionalProperties":false}'::json,next_content) then raise exception 'Nieprawidłowy format szkicu.'; end if;
 if length(trim(next_title)) not between 1 and 200 then raise exception 'Podaj nazwę wersji (1–200 znaków).'; end if;
 update public.curriculum_draft set title=next_title,content=next_content,revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=1 and revision=expected_revision returning * into d;
 if not found then raise exception 'Wersja robocza zmieniła się w innej karcie. Pobierz ją ponownie; Twoje zmiany pozostają w formularzu.' using errcode='40001'; end if;
 return d;
end;
$$;
create or replace function public.validate_curriculum(c jsonb, previous jsonb default null) returns void language plpgsql set search_path='' as $$
declare l jsonb; s jsonb; old jsonb; n jsonb;
begin
 if not extensions.jsonb_matches_schema('{"type":"object","properties":{"schemaVersion":{"const":1},"chapters":{"type":"array","items":{"type":"object","properties":{"id":{"type":"integer","minimum":1,"maximum":30},"title":{"type":"string","minLength":1,"maxLength":20000},"subtitle":{"type":"string","minLength":1,"maxLength":20000},"region":{"type":"string","minLength":1,"maxLength":20000}},"required":["id","title","subtitle","region"],"additionalProperties":false},"minItems":1,"maxItems":30},"lessons":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"chapter":{"type":"integer","minimum":1,"maximum":1000000},"order":{"type":"integer","minimum":1,"maximum":1000000},"title":{"type":"string","minLength":1,"maxLength":20000},"category":{"enum":["Technika","Rytm","Teoria","Słuch","Repertuar","Improwizacja"]},"theory":{"type":"string","minLength":1,"maxLength":20000},"steps":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"example":{"type":"string","minLength":1,"maxLength":20000},"criteria":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"mistake":{"type":"string","minLength":1,"maxLength":20000},"source":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"prerequisites":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":0,"maxItems":5000,"uniqueItems":true},"optional":{"type":"boolean"},"challenge":{"type":"boolean"},"minutes":{"type":"integer","minimum":1,"maximum":180},"sessions":{"type":"array","items":{"type":"integer","minimum":1,"maximum":1000000},"minItems":2,"maxItems":2},"branch":{"type":"string","minLength":1,"maxLength":20000},"songChoices":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":1,"maxItems":10,"uniqueItems":true}},"required":["id","chapter","order","title","category","theory","steps","example","criteria","mistake","source","prerequisites","optional","challenge","minutes"],"additionalProperties":false},"minItems":1,"maxItems":5000},"songs":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"title":{"type":"string","minLength":1,"maxLength":20000},"artist":{"type":"string","minLength":1,"maxLength":20000},"kind":{"enum":["Piosenka","Riff","Aranżacja"]},"chapter":{"type":"integer","minimum":1,"maximum":1000000},"version":{"type":"string","minLength":1,"maxLength":20000},"requirements":{"type":"array","items":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"minItems":0,"maxItems":5000,"uniqueItems":true},"example":{"type":"string","maxLength":20000},"url":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000},"lesson":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"teacher":{"type":"string","minLength":1,"maxLength":20000},"language":{"type":"string","minLength":1,"maxLength":20000},"practice":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"criteria":{"type":"array","items":{"type":"string","minLength":1,"maxLength":20000},"minItems":1,"maxItems":5000},"nylon":{"type":"string","minLength":1,"maxLength":20000},"sessions":{"type":"array","items":{"type":"integer","minimum":1,"maximum":1000000},"minItems":2,"maxItems":2},"checkpoint":{"type":"integer","minimum":1,"maximum":1000000},"extraUrl":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000}},"required":["id","title","artist","kind","chapter","version","requirements","example"],"additionalProperties":false},"minItems":0,"maxItems":5000},"sources":{"type":"object","minProperties":1,"maxProperties":5000,"propertyNames":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,79}$"},"additionalProperties":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":20000},"url":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":2000},"language":{"type":"string","minLength":1,"maxLength":20000},"access":{"type":"string","minLength":1,"maxLength":20000}},"required":["title","url","language","access"],"additionalProperties":false}}},"required":["schemaVersion","chapters","lessons","songs","sources"],"additionalProperties":false}'::json,c) then raise exception 'Program nie spełnia schematu treści.'; end if;
 if exists(select 1 from jsonb_array_elements(c->'lessons') x group by x->>'id' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(c->'songs') x group by x->>'id' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(c->'chapters') x group by x->>'id' having count(*)>1) then raise exception 'Powtórzone identyfikatory.'; end if;
 if exists(select 1 from jsonb_array_elements(c->'chapters') with ordinality x(ch,idx) where (ch->>'id')::int<>idx) then raise exception 'Nieprawidłowa kolejność rozdziałów.'; end if;
 for l in select value from jsonb_array_elements(c->'lessons') loop
  if not exists(select 1 from jsonb_array_elements(c->'chapters') ch where ch->'id'=l->'chapter') or not(c->'sources' ? (l->>'source')) or exists(select 1 from jsonb_array_elements_text(l->'prerequisites') p where not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->>'id'=p)) then raise exception 'Nieistniejące wymaganie, rozdział lub źródło: %',l->>'id'; end if;
  if l ? 'sessions' and (l->'sessions'->>0)::int>(l->'sessions'->>1)::int then raise exception 'Odwrócony zakres sesji.'; end if;
  if l ? 'songChoices' then
   if not(l->>'challenge')::boolean then raise exception 'Wybór utworu musi być wyzwaniem.'; end if;
   for s in select value from jsonb_array_elements(l->'songChoices') loop
    select value into n from jsonb_array_elements(c->'songs') x where x->'id'=s;
    if n is null or not(n ? 'url') or not(n ? 'practice') or not(n ? 'criteria') or n->'checkpoint' is distinct from l->'chapter' then raise exception 'Niekompletny utwór sceny.'; end if;
   end loop;
  end if;
 end loop;
 for s in select value from jsonb_array_elements(c->'songs') loop
  if not exists(select 1 from jsonb_array_elements(c->'chapters') ch where ch->'id'=s->'chapter')
  or exists(select 1 from jsonb_array_elements_text(s->'requirements') p where not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->>'id'=p))
  or (s ? 'lesson' and not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->'id'=s->'lesson'))
  or (s ? 'checkpoint' and not exists(select 1 from jsonb_array_elements(c->'chapters') x where x->'id'=s->'checkpoint')) then raise exception 'Nieistniejące wymagania utworu.'; end if;
  if s ? 'sessions' and (s->'sessions'->>0)::int>(s->'sessions'->>1)::int then raise exception 'Odwrócony zakres sesji utworu.'; end if;
 end loop;
 if exists(with recursive edges as (select x->>'id' id,p dep from jsonb_array_elements(c->'lessons') x cross join lateral jsonb_array_elements_text(x->'prerequisites') p), walk as (select id,dep,array[id] path,dep=id cycle from edges union all select w.id,e.dep,w.path||w.dep,e.dep=any(w.path||w.dep) from walk w join edges e on e.id=w.dep where not w.cycle) select 1 from walk where cycle) then raise exception 'Pętla wymagań w programie.'; end if;
 if exists(select 1 from jsonb_array_elements(c->'chapters') ch where not exists(select 1 from jsonb_array_elements(c->'lessons') x where x->'chapter'=ch->'id' and x->>'optional'='false')) or exists(select 1 from jsonb_array_elements(c->'lessons') x where x->>'optional'='false' group by x->>'chapter',x->>'order' having count(*)>1) then raise exception 'Rozdział bez trasy lub powtórzona kolejność.'; end if;
 if previous is not null then
  for old in select value from jsonb_array_elements(previous->'lessons') loop
   select value into n from jsonb_array_elements(c->'lessons') x where x->'id'=old->'id';
   if n is null or n->'challenge'<>old->'challenge' or n->'optional'<>old->'optional' or n->'chapter'<>old->'chapter' then raise exception 'Zachowaj identyfikatory, rozdział, rodzaj i XP opublikowanych zadań.'; end if;
   if (old ? 'songChoices' and not(coalesce(n->'songChoices','[]'::jsonb) @> (old->'songChoices'))) or (not(old ? 'songChoices') and n ? 'songChoices') then raise exception 'Zachowaj historyczne wybory utworów.'; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(previous->'songs') prior_song where not exists(select 1 from jsonb_array_elements(c->'songs') x where x->'id'=prior_song->'id')) or exists(select 1 from jsonb_array_elements(previous->'chapters') prior_chapter where not exists(select 1 from jsonb_array_elements(c->'chapters') x where x->'id'=prior_chapter->'id')) then raise exception 'Nie można usunąć opublikowanych utworów lub rozdziałów.'; end if;
 end if;
end;
$$;
commit;
